import { Global, Theme, Token } from '@pleat/core'

/** Complex-domain tokens (sidebar, charts, overlays). */
const complexTokensSpec = Token.make(
  {
    sidebar: Token.color,
    sidebarForeground: Token.color,
    sidebarPrimary: Token.color,
    sidebarPrimaryForeground: Token.color,
    sidebarAccent: Token.color,
    sidebarAccentForeground: Token.color,
    sidebarBorder: Token.color,
    sidebarRing: Token.color,
    chart1: Token.color,
    chart2: Token.color,
    chart3: Token.color,
    chart4: Token.color,
    chart5: Token.color,
    mutedSurface: Token.color,
    opaqueMutedSurface: Token.color,
    accentSurface: Token.color,
    opaqueAccentSurface: Token.color,
    focusOutline: Token.value,
    resizeShadow: Token.value,
    smallRadius: Token.length,
    overlaySurface: Token.color,
    transparent: Token.color,
    sidebarEdgeRing: Token.value,
    sidebarAccentRing: Token.value,
    sidebarForegroundDim: Token.color,
    chart1Soft10: Token.color,
    chart2Soft10: Token.color,
    chart3Soft10: Token.color,
    chart2Soft15: Token.color,
    chart3Soft15: Token.color,
    chart4Soft15: Token.color,
    chart2Soft25: Token.color,
    destructiveSoft15: Token.color,
    chart2Soft20: Token.color,
    chart4Soft20: Token.color,
    destructiveSoft20: Token.color,
    chart4Soft5: Token.color,
    successSoft20: Token.color,
    warningSoft20: Token.color,
    warningSoft5: Token.color,
    destructiveSoft6: Token.color,
  },
  { prefix: 'crease-complex-' },
)

export const complexTokens = complexTokensSpec

export const complexTokensTheme = Theme.make(complexTokensSpec, {
  sidebar: 'var(--sidebar)',
  sidebarForeground: 'var(--sidebar-foreground)',
  sidebarPrimary: 'var(--sidebar-primary)',
  sidebarPrimaryForeground: 'var(--sidebar-primary-foreground)',
  sidebarAccent: 'var(--sidebar-accent)',
  sidebarAccentForeground: 'var(--sidebar-accent-foreground)',
  sidebarBorder: 'var(--sidebar-border)',
  sidebarRing: 'var(--sidebar-ring)',
  chart1: 'var(--chart-1)',
  chart2: 'var(--chart-2)',
  chart3: 'var(--chart-3)',
  chart4: 'var(--chart-4)',
  chart5: 'var(--chart-5)',
  mutedSurface: 'color-mix(in oklab, var(--muted) 50%, transparent)',
  opaqueMutedSurface:
    'color-mix(in oklab, var(--muted) 50%, var(--background))',
  accentSurface: 'color-mix(in oklab, var(--accent) 50%, transparent)',
  opaqueAccentSurface:
    'color-mix(in oklab, var(--accent) 50%, var(--background))',
  focusOutline: '1px solid var(--ring)',
  resizeShadow: '0 0 0 1px var(--ring)',
  smallRadius: '2px',
  overlaySurface: 'color-mix(in oklab, var(--foreground) 50%, transparent)',
  transparent: 'transparent',
  sidebarEdgeRing: '0 0 0 1px var(--sidebar-border)',
  sidebarAccentRing: '0 0 0 1px var(--sidebar-accent)',
  sidebarForegroundDim:
    'color-mix(in oklab, var(--sidebar-foreground) 70%, transparent)',
  chart1Soft10: 'color-mix(in oklab, var(--chart-1) 10%, transparent)',
  chart2Soft10: 'color-mix(in oklab, var(--chart-2) 10%, transparent)',
  chart3Soft10: 'color-mix(in oklab, var(--chart-3) 10%, transparent)',
  chart2Soft15: 'color-mix(in oklab, var(--chart-2) 15%, transparent)',
  chart3Soft15: 'color-mix(in oklab, var(--chart-3) 15%, transparent)',
  chart4Soft15: 'color-mix(in oklab, var(--chart-4) 15%, transparent)',
  chart2Soft25: 'color-mix(in oklab, var(--chart-2) 25%, transparent)',
  destructiveSoft15: 'color-mix(in oklab, var(--destructive) 15%, transparent)',
  chart2Soft20: 'color-mix(in oklab, var(--chart-2) 20%, transparent)',
  chart4Soft20: 'color-mix(in oklab, var(--chart-4) 20%, transparent)',
  destructiveSoft20: 'color-mix(in oklab, var(--destructive) 20%, transparent)',
  chart4Soft5: 'color-mix(in srgb, var(--chart-4) 5%, transparent)',
  successSoft20: 'color-mix(in oklab, var(--success) 20%, transparent)',
  warningSoft20: 'color-mix(in oklab, var(--warning) 20%, transparent)',
  warningSoft5: 'color-mix(in srgb, var(--warning) 5%, transparent)',
  destructiveSoft6: 'color-mix(in srgb, var(--destructive) 6%, transparent)',
})

Global.theme(complexTokensTheme)
